package org.openenglish.reader;
import android.app.*;import android.os.*;import android.content.*;import android.text.*;import android.view.*;import android.widget.*;
import org.json.*;import java.util.*;import java.text.SimpleDateFormat;import java.util.concurrent.*;
/** Searchable, paged view over existing durable memory; no additional store or secrets. */
public final class IslandMemoryActivity extends Activity {
 private final Handler ui=new Handler(Looper.getMainLooper());private final ExecutorService writes=Executors.newSingleThreadExecutor();
 private String language="yue",scene=null;private IslandMemory memory;private EditText search;private TextView summary,note;private LinearLayout list;private Button more;private JSONArray matches=new JSONArray();private int shown;private boolean closed;
 private final Runnable refresh=()->render();
 private int dp(int n){return CosmicUi.dp(this,n);}
 private TextView text(LinearLayout parent,String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(CosmicUi.INK);v.setPadding(0,dp(8),0,dp(8));parent.addView(v);return v;}
 private Button button(LinearLayout parent,String s,Runnable action){Button b=new Button(this);b.setText(s);CosmicUi.button(b,false);b.setOnClickListener(v->action.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(8);parent.addView(b,p);return b;}
 private LinearLayout column(){LinearLayout p=new LinearLayout(this);p.setOrientation(1);return p;}
 @Override public void onCreate(Bundle state){super.onCreate(state);language=state==null?getIntent().getStringExtra("language"):state.getString("language","yue");if(!"ja".equals(language)&&!"zh".equals(language))language="yue";scene=state==null?getIntent().getStringExtra("scene"):state.getString("scene");memory=new IslandMemory(this,language);
  getWindow().setStatusBarColor(CosmicUi.BG);getWindow().setNavigationBarColor(CosmicUi.BG);FrameLayout sky=new FrameLayout(this);sky.addView(new CosmicUi.Sky(this));LinearLayout root=column();root.setBackgroundColor(0xdd10152c);root.setPadding(dp(18),dp(10),dp(18),dp(12));sky.addView(root,new FrameLayout.LayoutParams(-1,-1));setContentView(sky);
  button(root,"‹ 返回 · 麦克风保持暂停",this::finish);text(root,"☾ 露娜的记忆星图",24);text(root,"查找一起说过的话，再接着聊一小句",13).setTextColor(CosmicUi.MUTED);
  LinearLayout tabs=new LinearLayout(this);for(String l:new String[]{"yue","ja","zh"}){Button b=new Button(this);b.setText(IslandScene.name(l));CosmicUi.button(b,l.equals(language));b.setOnClickListener(v->{language=l;scene=null;memory=new IslandMemory(this,l);search.setText("");render();for(int i=0;i<tabs.getChildCount();i++)CosmicUi.button((TextView)tabs.getChildAt(i),tabs.getChildAt(i)==v);});tabs.addView(b,new LinearLayout.LayoutParams(0,-2,1));}root.addView(tabs);
  search=new EditText(this);search.setTextColor(CosmicUi.INK);search.setHintTextColor(CosmicUi.MUTED);search.setHint("找一句话、场景或露娜的回答");search.setSingleLine();search.setFilters(new InputFilter[]{new InputFilter.LengthFilter(100)});root.addView(search);
  if(state!=null)search.setText(state.getString("query",""));search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int start,int before,int count){ui.removeCallbacks(refresh);ui.postDelayed(refresh,200);}public void afterTextChanged(Editable e){}});
  button(root,"选择场景 · 全部 / 按场景查看",this::chooseScene);summary=text(root,"",13);summary.setMaxLines(2);summary.setEllipsize(TextUtils.TruncateAt.END);
  ScrollView scroll=new ScrollView(this);LinearLayout content=column();note=text(content,"",13);note.setTextColor(CosmicUi.MUTED);note.setMaxLines(3);note.setEllipsize(TextUtils.TruncateAt.END);button(content,"想让露娜记住 · 编辑学习偏好",this::editNote);list=column();content.addView(list);more=button(content,"再展开 20 轮",this::appendPage);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));render();
 }
 private void chooseScene(){List<String> scenes=memory.scenes();String[] labels=new String[scenes.size()+1];labels[0]="全部场景";for(int i=0;i<scenes.size();i++)labels[i+1]=scenes.get(i);new AlertDialog.Builder(this).setTitle(IslandScene.name(language)+" · 选择场景").setItems(labels,(d,n)->{scene=n==0?null:scenes.get(n-1);render();}).setNegativeButton("返回",null).show();}
 private void render(){if(closed||search==null)return;matches=memory.search(search.getText().toString(),scene);shown=0;list.removeAllViews();summary.setText(IslandScene.name(language)+" · "+(scene==null?"全部场景":scene)+"\n找到 "+matches.length()+" 轮 / 已保存 "+memory.count()+" 轮（每门最多 300）");note.setText("学习偏好："+(memory.note().isEmpty()?"还没填写，露娜等你告诉她":memory.note()));if(matches.length()==0)text(list,search.getText().length()>0?"没找到这句，试试短一点的关键词。":"这里还空着。从魔法岛选个场景，完成一轮对话就会留下记忆 ✦",16);appendPage();}
 private void appendPage(){int end=Math.min(shown+20,matches.length());for(int i=shown;i<end;i++){JSONObject p=matches.optJSONObject(i);LinearLayout card=column();card.setPadding(dp(14),dp(10),dp(14),dp(14));card.setBackground(CosmicUi.panel(this,0xff292643,0xff1a2840,22));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(12);list.addView(card,lp);text(card,p.optString("scene")+" · "+new SimpleDateFormat("MM-dd HH:mm",Locale.CHINA).format(new Date(p.optLong("time"))),12).setTextColor(CosmicUi.MUTED);text(card,"你："+p.optString("user"),16).setTextIsSelectable(true);text(card,"☾ 露娜："+p.optString("assistant"),16).setTextIsSelectable(true);button(card,"接回这个小故事 ✦",()->continueScene(p.optString("scene")));button(card,"复制这一轮",()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("魔法岛对话",IslandScene.name(language)+" · "+p.optString("scene")+"\n你："+p.optString("user")+"\n露娜："+p.optString("assistant")));toast("这一轮已复制");});}shown=end;more.setVisibility(shown<matches.length()?View.VISIBLE:View.GONE);}
 private void editNote(){final IslandMemory target=memory;final String code=language;EditText input=new EditText(this);input.setText(target.note());input.setHint("慢一点；练点餐；提醒我长音……");input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(500)});new AlertDialog.Builder(this).setTitle(IslandScene.name(code)+" · 学习偏好").setView(input).setPositiveButton("记住啦",(d,n)->{String value=input.getText().toString();writes.execute(()->{try{target.note(value);ui.post(()->{if(!closed){toast("露娜已记住 "+IslandScene.name(code)+" 的偏好 ✦");render();}});}catch(Exception e){ui.post(()->{if(!closed)toast(e.getMessage());});}});}).setNegativeButton("返回",null).show();}
 private void continueScene(String value){if(value.trim().isEmpty()||value.length()>500){toast("场景未能打开");return;}SharedPreferences p=getSharedPreferences("language_magic",0);StudioStore store=new StudioStore(this);String key="scene_"+language+"_"+value;long id=p.getLong(key,0);JSONObject existing=store.session(id);String meta="magic:"+language+":"+value;if(existing==null||!meta.equals(existing.optString("scene"))){id=store.addSession("魔法岛 · "+IslandScene.name(language)+" · "+value,meta);p.edit().putLong(key,id).apply();}store.close();p.edit().putString("last_scene_"+language,value).apply();startActivity(new Intent(this,MagicDuplexActivity.class).putExtra("topic",id).putExtra("language",language));finish();}
 private void toast(String s){Toast.makeText(this,s==null?"暂时未能保存，请重试":s,Toast.LENGTH_SHORT).show();}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("language",language);b.putString("scene",scene);b.putString("query",search.getText().toString());}
 @Override protected void onDestroy(){closed=true;ui.removeCallbacksAndMessages(null);writes.shutdownNow();super.onDestroy();}
}
